"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator. See module docs.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_IDENT = r"[0-9A-Za-z-]+"
_VERSION = re.compile(rf"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-({_IDENT}(?:\.{_IDENT})*))?(?:\+({_IDENT}(?:\.{_IDENT})*))?\Z", re.ASCII)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += "-" + ".".join(self.prerelease)
        if self.build:
            result += "+" + ".".join(self.build)
        return result


def parse(text: str) -> Version:
    if not isinstance(text, str):
        raise ValueError("version must be a string")
    match = _VERSION.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre, build = match.groups()
    prerelease = tuple(pre.split(".")) if pre else ()
    if any(len(x) > 1 and x.startswith("0") and x.isdigit() for x in prerelease):
        raise ValueError(f"invalid version: {text!r}")
    return Version(int(major), int(minor), int(patch), prerelease,
                   tuple(build.split(".")) if build else ())


def _version(value: str | Version) -> Version:
    return parse(value) if isinstance(value, str) else value


def _cmp(a: Version, b: Version) -> int:
    for x, y in zip((a.major, a.minor, a.patch), (b.major, b.minor, b.patch)):
        if x != y:
            return 1 if x > y else -1
    if not a.prerelease or not b.prerelease:
        return (bool(a.prerelease) < bool(b.prerelease)) - (bool(a.prerelease) > bool(b.prerelease))
    for x, y in zip(a.prerelease, b.prerelease):
        if x == y:
            continue
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            return (int(x) > int(y)) - (int(x) < int(y))
        if xn != yn:
            return -1 if xn else 1
        return 1 if x > y else -1
    return (len(a.prerelease) > len(b.prerelease)) - (len(a.prerelease) < len(b.prerelease))


def compare(a: str | Version, b: str | Version) -> int:
    return _cmp(_version(a), _version(b))


def satisfies(version: str | Version, range_: str) -> bool:
    v = _version(version)
    if not isinstance(range_, str) or not range_.strip():
        raise ValueError("empty range")
    sets = range_.split("||")
    if any(not part.strip() for part in sets):
        raise ValueError("empty comparator set")
    for group in sets:
        tokens = group.split()
        comparators: list[tuple[str, Version]] = []
        for token in tokens:
            m = re.fullmatch(r"(\^|~|>=|<=|>|<|=)?(.+)", token)
            if not m:
                raise ValueError(f"invalid comparator: {token}")
            op, raw = m.groups()
            ver = parse(raw)
            if op in ("^", "~"):
                upper = (Version(ver.major + 1, 0, 0) if op == "^" and ver.major else
                         Version(0, ver.minor + 1, 0) if op == "^" and ver.minor else
                         Version(0, 0, ver.patch + 1) if op == "^" else
                         Version(ver.major, ver.minor + 1, 0))
                comparators.extend(((">=", ver), ("<", upper)))
            else:
                comparators.append((op or "=", ver))
        if not tokens:
            raise ValueError("empty comparator set")
        if v.prerelease and not any(c.prerelease and (v.major, v.minor, v.patch) == (c.major, c.minor, c.patch) for _, c in comparators):
            continue
        def holds(op: str, c: Version) -> bool:
            n = _cmp(v, c)
            return {"=": n == 0, ">": n > 0, ">=": n >= 0, "<": n < 0, "<=": n <= 0}[op]
        if all(holds(op, c) for op, c in comparators):
            return True
    return False
